var e={knownGoodPack:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Crea uno snapshot della configurazione funzionante della stampante come pacchetto, da ripristinare dopo una modifica errata.`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Annulla`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Nessun pacchetto ancora. Creane uno mentre la stampante è configurata come preferisci.`}},files:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` file di configurazione`}]}},create:{label:{t:0,b:{t:2,i:[{t:3}],s:`Nuovo pacchetto`}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:`es. SV08 funzionante - prima della taratura`}},button:{t:0,b:{t:2,i:[{t:3}],s:`Crea pacchetto`}}},restore:{button:{t:0,b:{t:2,i:[{t:3}],s:`Ripristina`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Sovrascrivere la configurazione attuale con questo pacchetto?`}},note:{t:0,b:{t:2,i:[{t:3}],s:`Il ripristino sovrascrive i tuoi file di configurazione; riavvia Klipper in seguito per applicarli.`}},restored:{t:0,b:{t:2,i:[{t:3,v:`Ripristinati `},{t:4,k:`count`},{t:3,v:` file di configurazione - riavvia Klipper per applicare`}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:`La stampante è occupata - impossibile ripristinare ora`}},not_found:{t:0,b:{t:2,i:[{t:3}],s:`I file del pacchetto sono mancanti`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Questo pacchetto non contiene file`}},moonraker_error:{t:0,b:{t:2,i:[{t:3,v:`Impossibile ripristinare: `},{t:4,k:`error`}]}}},delete:{button:{t:0,b:{t:2,i:[{t:3}],s:`Elimina`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Elimina pacchetto`}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Guida`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Guida ai pacchetti Known-Good`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Chiudi`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cos'è un pacchetto Known-Good?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Uno snapshot di ogni file di configurazione della stampante (printer.cfg e i suoi include) salvato come pacchetto con un nome. Quando la stampante stampa bene, crea un pacchetto così puoi tornare indietro se una modifica successiva rompe qualcosa.`}}},restore:{title:{t:0,b:{t:2,i:[{t:3}],s:`Ripristinare un pacchetto`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Il ripristino riscrive i file del pacchetto sulla configurazione attuale. Viene rifiutato mentre la stampante è occupata, e in seguito devi riavviare Klipper affinché la configurazione ripristinata abbia effetto.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glossario`}}}},glossary:{configPack:{term:{t:0,b:{t:2,i:[{t:3}],s:`Pacchetto di configurazione`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Un insieme salvato di tutti i file di configurazione della stampante in un dato momento.`}}},restorePoint:{term:{t:0,b:{t:2,i:[{t:3}],s:`Punto di ripristino`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Uno stato funzionante a cui puoi tornare - qui, un pacchetto creato mentre la stampante funzionava.`}}}}}}};export{e as default};